/**
 * Returns elements matching predicate — does not mutate input.
 * @param {number[]} values
 * @param {(n: number) => boolean} predicate
 * @returns {number[]}
 */
export function filterValues(values, predicate) {
  if (!Array.isArray(values)) {
    throw new TypeError("values must be an array");
  }
  return values.filter(predicate);
}

/**
 * @param {string} raw
 * @returns {number}
 * @throws {TypeError|RangeError}
 */
export function parsePositiveInt(raw) {
  if (typeof raw !== "string") {
    throw new TypeError("raw must be a string");
  }
  const value = Number.parseInt(raw, 10);
  if (!Number.isInteger(value) || value <= 0 || String(value) !== raw.trim()) {
    throw new RangeError("raw must be a positive integer");
  }
  return value;
}

/**
 * @param {number[]} nums
 * @returns {number[]}
 */
export function uniqueSorted(nums) {
  if (!Array.isArray(nums)) {
    throw new TypeError("nums must be an array");
  }
  return [...new Set(nums)].sort((a, b) => a - b);
}

/**
 * @template T
 * @param {T[]} items
 * @param {(item: T) => string} keyFn
 * @returns {Record<string, T[]>}
 */
export function groupBy(items, keyFn) {
  if (!Array.isArray(items)) {
    throw new TypeError("items must be an array");
  }
  /** @type {Record<string, T[]>} */
  const groups = Object.create(null);
  for (const item of items) {
    const key = keyFn(item);
    if (!Object.hasOwn(groups, key)) {
      groups[key] = [];
    }
    groups[key].push(item);
  }
  return groups;
}

/**
 * @param {string} text
 * @returns {{ ok: true, value: unknown } | { ok: false, error: Error }}
 */
export function safeJsonParse(text) {
  try {
    return { ok: true, value: JSON.parse(text) };
  } catch (cause) {
    const error = cause instanceof Error ? cause : new Error(String(cause));
    return { ok: false, error };
  }
}

/**
 * @template {(...args: unknown[]) => void} F
 * @param {F} fn
 * @param {number} waitMs
 * @returns {((...args: Parameters<F>) => void) & { cancel: () => void }}
 */
export function debounce(fn, waitMs) {
  /** @type {ReturnType<typeof setTimeout> | undefined} */
  let timer;
  const wrapped = (...args) => {
    if (timer !== undefined) {
      clearTimeout(timer);
    }
    timer = setTimeout(() => {
      timer = undefined;
      fn(...args);
    }, waitMs);
  };
  wrapped.cancel = () => {
    if (timer !== undefined) {
      clearTimeout(timer);
      timer = undefined;
    }
  };
  return wrapped;
}

/**
 * @param {number} n
 * @param {number} min
 * @param {number} max
 * @returns {number}
 */
export function clamp(n, min, max) {
  if (min > max) {
    throw new RangeError("min must be <= max");
  }
  return Math.min(max, Math.max(min, n));
}

/**
 * @param {Record<string, string | null | undefined>} params
 * @returns {string}
 */
export function toQueryString(params) {
  const parts = [];
  for (const [key, value] of Object.entries(params)) {
    if (value === null || value === undefined) {
      continue;
    }
    parts.push(`${encodeURIComponent(key)}=${encodeURIComponent(value)}`);
  }
  return parts.join("&");
}

/**
 * @template T
 * @param {T} obj
 * @returns {T}
 */
export function deepFreeze(obj) {
  if (obj === null || typeof obj !== "object") {
    return obj;
  }
  for (const value of Object.values(obj)) {
    deepFreeze(value);
  }
  return Object.freeze(obj);
}

/**
 * @param {never} x
 * @returns {never}
 */
export function assertNever(x) {
  throw new TypeError(`Unexpected value: ${String(x)}`);
}
